import{_ as e,o as i,c as r,ak as l}from"./chunks/framework.DJ-92fJv.js";const b=JSON.parse('{"title":"❓ 常见问题","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"start/faq.md","filePath":"start/faq.md"}'),o={name:"start/faq.md"};function s(t,a,h,n,d,c){return i(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="❓-常见问题" tabindex="-1">❓ 常见问题 <a class="header-anchor" href="#❓-常见问题" aria-label="Permalink to “❓ 常见问题”">​</a></h1><h2 id="基础问题" tabindex="-1">基础问题 <a class="header-anchor" href="#基础问题" aria-label="Permalink to “基础问题”">​</a></h2><h3 id="q-脚本运行后闪退怎么办" tabindex="-1">Q：脚本运行后闪退怎么办？ <a class="header-anchor" href="#q-脚本运行后闪退怎么办" aria-label="Permalink to “Q：脚本运行后闪退怎么办？”">​</a></h3><p><strong>可能原因与解决方案：</strong></p><ol><li><strong>杀毒软件拦截</strong> — 某些杀软会拦截脚本的进程/服务操作，请添加白名单或暂时关闭杀软</li><li><strong>权限不足</strong> — 有些系统策略禁止运行 <code>.bat</code> 文件，请右键选择「以管理员身份运行」</li><li><strong>路径含空格</strong> — 确保文件路径不含特殊字符</li></ol><h3 id="q-为什么提示-不是内部或外部命令" tabindex="-1">Q：为什么提示&quot;不是内部或外部命令&quot;？ <a class="header-anchor" href="#q-为什么提示-不是内部或外部命令" aria-label="Permalink to “Q：为什么提示&quot;不是内部或外部命令&quot;？”">​</a></h3><p>脚本依赖 Windows 自带的 <code>sc</code>、<code>taskkill</code>、<code>tasklist</code>、<code>powershell</code> 等命令。如果你的系统精简版移除了这些组件，可能无法正常运行。完整版 Windows 7/8/10/11 均自带。</p><h3 id="q-脚本被杀毒软件报毒怎么办" tabindex="-1">Q：脚本被杀毒软件报毒怎么办？ <a class="header-anchor" href="#q-脚本被杀毒软件报毒怎么办" aria-label="Permalink to “Q：脚本被杀毒软件报毒怎么办？”">​</a></h3><p>脚本的操作（终止进程、删除服务、删除驱动文件）与病毒行为类似，导致杀软误报。解决方案：</p><ul><li>将脚本添加至杀软白名单/信任区</li><li>临时关闭实时监控（不推荐长期关闭）</li><li>可以使用在线查毒平台验证脚本安全性</li></ul><h3 id="q-需要联网才能使用吗" tabindex="-1">Q：需要联网才能使用吗？ <a class="header-anchor" href="#q-需要联网才能使用吗" aria-label="Permalink to “Q：需要联网才能使用吗？”">​</a></h3><p><strong>不需要。</strong> 脚本是纯本地批处理文件，完全离线运行，不需要网络连接。</p><hr><h2 id="功能相关问题" tabindex="-1">功能相关问题 <a class="header-anchor" href="#功能相关问题" aria-label="Permalink to “功能相关问题”">​</a></h2><h3 id="q-一键解锁后-过一会儿又被控制了怎么办" tabindex="-1">Q：一键解锁后，过一会儿又被控制了怎么办？ <a class="header-anchor" href="#q-一键解锁后-过一会儿又被控制了怎么办" aria-label="Permalink to “Q：一键解锁后，过一会儿又被控制了怎么办？”">​</a></h3><p>这是因为噢易学生端有<strong>自动保护机制</strong>，某些进程被终止后会<strong>自动重启</strong>。</p><p><strong>解决方案：</strong></p><ol><li>再次运行一键解锁</li><li>然后进入 <strong>进程管理 → 持续监控模式</strong>（选项 11）</li><li>持续监控模式会每 2 秒自动终止关键进程，防止反弹</li></ol><h3 id="q-解锁后会影响正常上课吗" tabindex="-1">Q：解锁后会影响正常上课吗？ <a class="header-anchor" href="#q-解锁后会影响正常上课吗" aria-label="Permalink to “Q：解锁后会影响正常上课吗？”">​</a></h3><p>不会影响电脑的基本使用。解锁后你可以：</p><ul><li>正常上网浏览</li><li>正常使用键盘鼠标</li><li>正常使用U盘</li><li><strong>唯一变化</strong>：学生端管理功能被绕过，老师端可能显示该机器离线</li></ul><h3 id="q-如何恢复usb限制" tabindex="-1">Q：如何恢复USB限制？ <a class="header-anchor" href="#q-如何恢复usb限制" aria-label="Permalink to “Q：如何恢复USB限制？”">​</a></h3><p>由于 <code>easyusbflt</code> 服务已被删除，如需恢复：</p><ol><li>重新安装噢易学生端软件</li><li>或联系机房管理员恢复环境</li></ol><h3 id="q-processprotect-exe-杀不死怎么办" tabindex="-1">Q：ProcessProtect.exe 杀不死怎么办？ <a class="header-anchor" href="#q-processprotect-exe-杀不死怎么办" aria-label="Permalink to “Q：ProcessProtect.exe 杀不死怎么办？”">​</a></h3><p><code>ProcessProtect.exe</code> 是噢易的进程保护程序，存在自我保护机制。如果 <code>taskkill</code> 无法终止：</p><ul><li>尝试先停止 <code>MMPC</code> 服务（它可能负责保护该进程）</li><li>使用挂起功能暂停而非终止</li></ul><h3 id="q-一键解锁花了多长时间" tabindex="-1">Q：一键解锁花了多长时间？ <a class="header-anchor" href="#q-一键解锁花了多长时间" aria-label="Permalink to “Q：一键解锁花了多长时间？”">​</a></h3><p>通常 <strong>10~20 秒</strong> 内即可完成全部 5 个步骤。每个步骤之间有短暂的命令执行时间。</p><hr><h2 id="兼容性问题" tabindex="-1">兼容性问题 <a class="header-anchor" href="#兼容性问题" aria-label="Permalink to “兼容性问题”">​</a></h2><h3 id="q-脚本支持-windows-11-吗" tabindex="-1">Q：脚本支持 Windows 11 吗？ <a class="header-anchor" href="#q-脚本支持-windows-11-吗" aria-label="Permalink to “Q：脚本支持 Windows 11 吗？”">​</a></h3><p>支持。已在 Windows 10 和 Windows 11 上测试通过。Windows 7/8 同样兼容。</p><h3 id="q-适用于所有噢易版本吗" tabindex="-1">Q：适用于所有噢易版本吗？ <a class="header-anchor" href="#q-适用于所有噢易版本吗" aria-label="Permalink to “Q：适用于所有噢易版本吗？”">​</a></h3><p>脚本针对常见的噢易多媒体教学系统设计，大部分学校机房使用的版本均可兼容。如果发现某个功能无效，请检查学生端版本是否使用了不同的进程/服务名。</p><h3 id="q-可以在-64-位系统上运行吗" tabindex="-1">Q：可以在 64 位系统上运行吗？ <a class="header-anchor" href="#q-可以在-64-位系统上运行吗" aria-label="Permalink to “Q：可以在 64 位系统上运行吗？”">​</a></h3><p>完全可以。脚本会自动检测安装路径，优先检测 <code>Program Files (x86)</code>，兼容 x86 和 x64 系统。</p><hr><h2 id="技术问题" tabindex="-1">技术问题 <a class="header-anchor" href="#技术问题" aria-label="Permalink to “技术问题”">​</a></h2><h3 id="q-脚本如何实现管理员提权" tabindex="-1">Q：脚本如何实现管理员提权？ <a class="header-anchor" href="#q-脚本如何实现管理员提权" aria-label="Permalink to “Q：脚本如何实现管理员提权？”">​</a></h3><p>通过 PowerShell 调用 <code>Start-Process</code> 并指定 <code>-Verb RunAs</code> 参数，以管理员身份重新启动自身：</p><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Start-Process</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%~f0&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Verb RunAs</span></span></code></pre></div><p>这是一种安全常见的提权方式，Windows UAC 会提示用户确认。</p><h3 id="q-如何自己修改脚本" tabindex="-1">Q：如何自己修改脚本？ <a class="header-anchor" href="#q-如何自己修改脚本" aria-label="Permalink to “Q：如何自己修改脚本？”">​</a></h3><p>使用记事本或任意文本编辑器打开 <code>.bat</code> 文件即可查看和修改代码。脚本结构清晰，包含主菜单、子程序、功能模块等注释分区。</p><h3 id="q-可以添加新的解锁项吗" tabindex="-1">Q：可以添加新的解锁项吗？ <a class="header-anchor" href="#q-可以添加新的解锁项吗" aria-label="Permalink to “Q：可以添加新的解锁项吗？”">​</a></h3><p>当然可以。脚本是开源的 Bat 脚本，你可以：</p><ol><li>在 <code>:main_menu</code> 中添加新菜单项</li><li>新增对应的功能标签（如 <code>:unlock_new_feature</code>）</li><li>按现有子程序格式编写功能代码</li></ol><hr><h2 id="其他问题" tabindex="-1">其他问题 <a class="header-anchor" href="#其他问题" aria-label="Permalink to “其他问题”">​</a></h2><h3 id="q-这个工具的开发者是谁" tabindex="-1">Q：这个工具的开发者是谁？ <a class="header-anchor" href="#q-这个工具的开发者是谁" aria-label="Permalink to “Q：这个工具的开发者是谁？”">​</a></h3><p>作者是 <strong>NyxFox</strong>。该工具最初基于 Python 脚本实现，后移植为纯 Bat 脚本，使其无需依赖任何运行环境即可运行。</p><h3 id="q-工具会更新吗" tabindex="-1">Q：工具会更新吗？ <a class="header-anchor" href="#q-工具会更新吗" aria-label="Permalink to “Q：工具会更新吗？”">​</a></h3><p>作者可能会根据噢易新版本的变化进行更新。请关注最新版本发布。</p><h3 id="q-使用这个工具会被老师发现吗" tabindex="-1">Q：使用这个工具会被老师发现吗？ <a class="header-anchor" href="#q-使用这个工具会被老师发现吗" aria-label="Permalink to “Q：使用这个工具会被老师发现吗？”">​</a></h3><p><strong>在一定程度上可能被发现。</strong> 当停止 <code>MMPC</code> 服务或终止 <code>Student.exe</code> 后，老师端的控制台可能会显示该机器离线或异常。使用时请注意周围环境。</p><h3 id="q-有-mac-linux-版本吗" tabindex="-1">Q：有 Mac/Linux 版本吗？ <a class="header-anchor" href="#q-有-mac-linux-版本吗" aria-label="Permalink to “Q：有 Mac/Linux 版本吗？”">​</a></h3><p>没有。噢易学生端仅存在于 Windows 环境中，本工具也只支持 Windows 平台。</p>',58)])])}const k=e(o,[["render",s]]);export{b as __pageData,k as default};
